using System;using System.IO;using System.IO.Compression;using System.Reflection;using System.Diagnostics;using System.Drawing;using System.Threading.Tasks;using System.Windows.Forms;
static class StandaloneReader {
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new ReaderWindow());}
}
sealed class ReaderWindow:Form {
 readonly Label status=new Label();readonly Button read=new Button();bool busy;string report;
 public ReaderWindow(){Text="LifeAC — Standalone reader";ClientSize=new Size(650,345);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(243,247,246);Font=new Font("Segoe UI",10);var title=new Label{Text="Read the standalone controller",Dock=DockStyle.Top,Height=72,BackColor=Color.FromArgb(46,88,110),ForeColor=Color.White,Font=new Font("Segoe UI",19,FontStyle.Bold),Padding=new Padding(22)};Controls.Add(title);var explanation=new Label{Text="On the projector PC, close Lighting and ProDMX first.\n\nThis check reads stored scene headers, triggers and DMX steps using the legacy communication found in ProDMX. It may pause playback. Scene reads are repeated to check consistency. Driver details, configured show and troubleshooting logs are included. No scene writes or live DMX frames are sent.",Bounds=new Rectangle(24,88,600,115)};Controls.Add(explanation);status.SetBounds(24,210,600,60);status.Text="Read all configured scenes in one step. This is not yet a proven full restoration backup.";Controls.Add(status);read.SetBounds(24,280,370,43);read.Text="Run complete check & export report";read.Click+=async(s,e)=>{if(report!=null){Process.Start(new ProcessStartInfo("explorer.exe","/select,\""+report+"\""){UseShellExecute=true});return;}busy=true;read.Enabled=false;status.Text="Reading… No scene-memory writes are enabled.";try{report=await Task.Run((Func<string>)Run);status.Text="Report saved. Attach this ZIP in our chat:\n"+Path.GetFileName(report);read.Text="Show report file";}catch(Exception error){status.Text="The check could not finish ("+error.GetType().Name+"). No memory-writing operation was requested.";}finally{busy=false;read.Enabled=true;}};Controls.Add(read);FormClosing+=(s,e)=>{if(busy)e.Cancel=true;};}
 static string Run(){string folder=Path.Combine(Path.GetTempPath(),"LifeAC-Standalone-Reader-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string exe=Path.Combine(folder,"reader-worker.exe");try{using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream("LifeAC.StandaloneReaderWorker"))using(var output=File.Create(exe))input.CopyTo(output);var info=new ProcessStartInfo(exe){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};string result="",errors="";int code;using(var child=new Process{StartInfo=info}){child.Start();var stdout=child.StandardOutput.ReadToEndAsync();var stderr=child.StandardError.ReadToEndAsync();if(!child.WaitForExit(600000)){child.Kill();child.WaitForExit();result="{\"ok\":false,\"error\":\"Read probe timed out; no memory-writing operation was requested. Physical playback after USB release is unconfirmed.\"}";}else result=stdout.Result;errors=stderr.Result;code=child.ExitCode;}if(String.IsNullOrWhiteSpace(result))result="{\"ok\":false,\"error\":\"The isolated USB worker stopped unexpectedly\",\"exitCode\":"+code+"}";string reports=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"LifeAC-Lighting","Reports");Directory.CreateDirectory(reports);string zip=Path.Combine(reports,"LifeAC-standalone-read-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6)+".zip");using(var archive=ZipFile.Open(zip,ZipArchiveMode.Create)){EnvironmentReport.Collect(archive);using(var writer=new StreamWriter(archive.CreateEntry("standalone-read.json").Open()))writer.Write(result);using(var writer=new StreamWriter(archive.CreateEntry("read-progress.txt").Open()))writer.Write(errors);using(var writer=new StreamWriter(archive.CreateEntry("README.txt").Open()))writer.Write("Experimental read-only standalone scene and step reader. This report is not a full memory backup or proof that writing is implemented. No driver changes, firmware updates, memory erase/write or DMX-frame output operation is implemented in this probe. Opaque device configuration may contain private show data. Nothing is uploaded automatically. Worker exit code: "+code+". Error output present: "+(!String.IsNullOrWhiteSpace(errors)));}return zip;}finally{if(File.Exists(exe))File.Delete(exe);if(Directory.Exists(folder))Directory.Delete(folder,false);}}
}
